create extension if not exists pgcrypto;\n\ncreate table if not exists employees (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid,\n  name text not null,\n  department text,\n  email text,\n  created_at timestamptz not null default now()\n);\n\ncreate table if not exists assets (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid,\n  asset_tag text not null unique,\n  asset_type text not null,\n  brand_model text not null,\n  serial_number text,\n  purchase_date date,\n  warranty_expiry date,\n  condition text default 'good',\n  location text,\n  assigned_employee_id uuid references employees(id),\n  status text not null default 'available',\n  notes text,\n  created_at timestamptz not null default now()\n);\n\ncreate table if not exists maintenance_logs (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid,\n  asset_id uuid not null references assets(id) on delete cascade,\n  log_type text not null,\n  description text,\n  logged_date date not null default current_date,\n  created_at timestamptz not null default now()\n);\n\nalter table employees enable row level security;\nalter table assets enable row level security;\nalter table maintenance_logs enable row level security;\n\ndrop policy if exists \"employees_v1_read\" on employees;\ncreate policy \"employees_v1_read\" on employees for select using (true);\ndrop policy if exists \"employees_v1_write\" on employees;\ncreate policy \"employees_v1_write\" on employees for all using (true) with check (true);\n\ndrop policy if exists \"assets_v1_read\" on assets;\ncreate policy \"assets_v1_read\" on assets for select using (true);\ndrop policy if exists \"assets_v1_write\" on assets;\ncreate policy \"assets_v1_write\" on assets for all using (true) with check (true);\n\ndrop policy if exists \"maintenance_logs_v1_read\" on maintenance_logs;\ncreate policy \"maintenance_logs_v1_read\" on maintenance_logs for select using (true);\ndrop policy if exists \"maintenance_logs_v1_write\" on maintenance_logs;\ncreate policy \"maintenance_logs_v1_write\" on maintenance_logs for all using (true) with check (true);\n\ninsert into employees (id, name, department, email) values\n  ('a0000000-0000-0000-0000-000000000001', 'Ahmad Rahman', 'Finance', 'ahmad.r@selangorprops.my'),\n  ('a0000000-0000-0000-0000-000000000002', 'Siti Aminah', 'IT', 'siti.a@selangorprops.my'),\n  ('a0000000-0000-0000-0000-000000000003', 'Tan Wei Ming', 'Operations', 'tan.wm@selangorprops.my')\non conflict (id) do nothing;\n\ninsert into assets (id, asset_tag, asset_type, brand_model, serial_number, purchase_date, warranty_expiry, condition, location, assigned_employee_id, status) values\n  ('b0000000-0000-0000-0000-000000000001', 'SPB-LT-001', 'Laptop', 'Dell Latitude 5440', 'DL5440SN001', '2024-01-15', '2027-01-15', 'good', 'HQ Floor 3', 'a0000000-0000-0000-0000-000000000001', 'assigned'),\n  ('b0000000-0000-0000-0000-000000000002', 'SPB-MN-002', 'Monitor', 'Dell UltraSharp U2723QE', 'DLMON002', '2023-06-20', '2025-06-20', 'good', 'HQ Floor 3', 'a0000000-0000-0000-0000-000000000001', 'assigned'),\n  ('b0000000-0000-0000-0000-000000000003', 'SPB-PH-003', 'Phone', 'iPhone 14', 'IP14SN003', '2023-03-10', '2025-03-10', 'fair', 'HQ Floor 5', 'a0000000-0000-0000-0000-000000000002', 'assigned'),\n  ('b0000000-0000-0000-0000-000000000004', 'SPB-LT-004', 'Laptop', 'Lenovo ThinkPad T14', 'LTT14SN004', '2022-11-05', '2024-11-05', 'poor', 'IT Store Room', null, 'available'),\n  ('b0000000-0000-0000-0000-000000000005', 'SPB-AC-005', 'Accessory', 'Logitech MX Master 3S', 'LOGMX005', '2024-05-01', '2026-05-01', 'good', 'IT Store Room', null, 'available')\non conflict (id) do nothing;\n\ninsert into maintenance_logs (id, asset_id, log_type, description, logged_date) values\n  ('c0000000-0000-0000-0000-000000000001', 'b0000000-0000-0000-0000-000000000003', 'repair', 'Screen replacement due to crack', '2024-08-12'),\n  ('c0000000-0000-0000-0000-000000000002', 'b0000000-0000-0000-0000-000000000004', 'maintenance', 'Battery health check and replacement', '2024-09-01')\non conflict (id) do nothing;\n\n-- Secondary tables deferred to later: audit_logs, teams, software_licenses